const $=s=>document.querySelector(s), $$=s=>document.querySelectorAll(s);
const initialInbox=[{type:'voice',title:'Field observation',text:'Sample demo: water looked cloudy at station 8. Check the sampling time.'},{type:'csv',title:'results_014.csv',text:'Sample dataset · linked to Experiment 014.'},{type:'image',title:'Sample photo',text:'Sample evidence · original source stays attached.'}];
const initialReviews=[{title:'Link field observation → Experiment 014',text:'Suggested from the shared station ID. Confirm the experiment before linking.'},{title:'Flag a missing collection time',text:'The sample observation has no collection time. Ask the researcher; do not invent one.'},{title:'Check a possible duplicate sample',text:'Two sample labels look similar. Keep both records until their identity is verified.'}];
let inbox=[],reviews=[]; const icons={voice:'♫',csv:'▦',image:'▧',text:'≡',audio:'♫',file:'▤'};
function esc(v){const e=document.createElement('span');e.textContent=v;return e.innerHTML}
function render(){ $('#inboxcount').textContent=inbox.length;const count=reviews.filter(r=>!r.status).length;$('#reviewcount').textContent=count;$('#tabcount').textContent=count;$('#inboxlist').innerHTML=inbox.map(r=>`<div class="record"><span>${icons[r.type]||'▤'}</span><div><strong>${esc(r.title)}</strong><p>${esc(r.text)}</p></div></div>`).join('');$('#reviewlist').innerHTML=reviews.map((r,i)=>`<div class="record"><span>✳</span><div><strong>${esc(r.title)}</strong><p>${esc(r.text)}</p></div>${r.status?`<span class="resolved">${esc(r.status)}</span>`:`<div class="reviewactions"><button data-review="${i}" data-action="Accepted in demo">Accept</button><button data-review="${i}" data-action="Dismissed">Dismiss</button></div>`}</div>`).join('');}
function view(v){['graph','inbox','review'].forEach(n=>$('#'+n+'view').classList.toggle('hidden',n!==v));$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#viewtitle').textContent={graph:'Everything has a place.',inbox:'Start with what you have.',review:'Good records grow with care.'}[v]}
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>view(b.dataset.view)));$('#reviewlist').addEventListener('click',e=>{const b=e.target.closest('[data-review]');if(!b)return;reviews[Number(b.dataset.review)].status=b.dataset.action;render()});
function reset(){inbox=structuredClone(initialInbox);reviews=structuredClone(initialReviews);render();view('graph');$('#capturestatus').textContent='Text, image, audio or CSV';$('#notetext').value='';$('#fileinput').value=''}$('#reset').addEventListener('click',reset);reset();
function add(type,title,text){inbox.unshift({type,title,text});reviews.unshift({title:'Assign '+title+' to a project',text:'New capture awaiting review. A connected local model would propose metadata and links here.'});render();view('inbox');$('#capturestatus').textContent='Added to this demo session';}
$('#captureform').addEventListener('submit',e=>{e.preventDefault();let t=$('#notetext').value.trim();if(!t){$('#capturestatus').textContent='Write an observation first';$('#notetext').focus();return}add('text','Research note',t);$('#notetext').value=''});$('#samplevoice').addEventListener('click',()=>{add('voice','Voice note example','Illustrative transcript: “Station 8, second replicate. Filtration took longer today. Please link the observation to Experiment 014.”');$('#capturestatus').textContent='Sample transcript added · microphone not used'});$('#upload').addEventListener('click',()=>$('#fileinput').click());$('#fileinput').addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;const ext=f.name.toLowerCase().split('.').pop();let type=f.type.startsWith('image/')?'image':f.type.startsWith('audio/')?'audio':ext==='csv'?'csv':'file';add(type,f.name,`${(f.size/1024).toFixed(1)} KB · File metadata captured in browser memory only. No upload, transcription or analysis performed.`);e.target.value=''});
const details={project:['◫','Water quality','Project hub: experiments, observations and datasets share one context.','Sample project'],experiment:['⚗','Experiment 014','Connected to its project, protocol version and original evidence.','Human-reviewed'],protocol:['≡','Filtration v2.1','Exact protocol version used for this experiment. Later edits should create a new version.','Version preserved'],note:['♫','Field observation','Original observation retained alongside any transcript and proposed links.','Source retained'],data:['▦','results_014.csv','A dataset should retain units, column meanings and the analysis that produced it.','Sample dataset'],image:['▧','Sample photo','Visual evidence linked to the experiment, with the original file preserved.','Sample evidence']};
function selectNode(el){const d=details[el.dataset.node];$('#nodedetail').innerHTML=`<span class="detailicon">${d[0]}</span><div><strong>${d[1]}</strong><p>${d[2]}</p></div><span class="detailtag">${d[3]}</span>`}$$('.node').forEach(el=>{el.addEventListener('click',()=>selectNode(el));el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectNode(el)}})});
$$('[data-project]').forEach(b=>b.addEventListener('click',()=>{$('#projectname').textContent=b.dataset.project;$$('[data-project]').forEach(p=>p.classList.toggle('selected',p===b));const name=b.dataset.project;document.querySelector('[data-node="project"] text:not(.symbol)').textContent=name;details.project[1]=name;view('graph');$('#capturestatus').textContent='Project context changed · sample records retained'}));
const ideas=[['START SMALL, FINISH THE LOOP','One capture. One proposed update. One review.','Start with text and CSV capture, project matching and source-backed update proposals. Add local speech and image models after the review loop works. An eLabFTW adapter would write only approved changes.','FIRST RELEASE: CAPTURE → LINK → REVIEW → EXPORT'],['MAKE THE METHOD REUSABLE','From a versioned protocol to a lesson people can follow.','Connect protocol versions to real experiment records. Let a helper draft prerequisites, steps and checks; a researcher reviews the method. Export curated Markdown for a Carpentries Workbench lesson.','FIRST RELEASE: VERSION → VALIDATE → CURATE → TEACH'],['GIVE THE PROJECT A MEMORY','See what is known, missing and waiting for a decision.','Build a graph of research questions, experiments, sources and decisions. Small local models suggest links and flag gaps. Every summary points back to evidence; uncertain relationships stay proposals.','FIRST RELEASE: IMPORT → MAP → TEND → TRACE']];$$('[data-idea]').forEach(b=>b.addEventListener('click',()=>{const d=ideas[Number(b.dataset.idea)];$$('[data-idea]').forEach(x=>x.classList.toggle('chosen',x===b));['ideakicker','ideatitle','ideacopy','ideascope'].forEach((id,i)=>$('#'+id).textContent=d[i])}));
